From 046048f2b5f1b85a033a0d25c244a2155a2f80e4 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 17:16:19 +0100
Subject: [PATCH] containments/panel: add apps dropped on a spacer to the
 nearby task manager

Dropping an application on a spacer next to the task manager added it as
a separate icon widget, which is rarely what's wanted. Such drops now pin
the app in the task manager, at the end that faces the drop point.

BUG: 507822
---
 containments/panel/main.qml | 37 +++++++++++++++++++++++++++++++++++--
 1 file changed, 35 insertions(+), 2 deletions(-)

diff --git a/containments/panel/main.qml b/containments/panel/main.qml
index 4ee220333e..9aef90a205 100644
--- a/containments/panel/main.qml
+++ b/containments/panel/main.qml
@@ -84,6 +84,36 @@ ContainmentItem {
         LayoutManager.reorderApplets(order);
     }

+    // When applications are dropped on a spacer next to a task manager,
+    // add them as launchers there instead of as separate icon widgets
+    function addLaunchersNextToSpacer(urls, index: int): bool {
+        const appletAt = i => i >= 0 && i < appletsModel.count ? appletsModel.get(i).applet : null;
+        const isSpacer = applet => applet?.plasmoid?.pluginName === "org.kde.plasma.panelspacer";
+        const supportsLaunchers = applet => applet?.supportsLaunchers === true;
+
+        const before = appletAt(index - 1);
+        const after = appletAt(index);
+        let taskManager = null;
+        let atStart = false;
+        if (isSpacer(before) && supportsLaunchers(after)) {
+            taskManager = after;
+            atStart = true;
+        } else if (isSpacer(after) && supportsLaunchers(before)) {
+            taskManager = before;
+        } else if (isSpacer(before) && supportsLaunchers(appletAt(index - 2))) {
+            taskManager = appletAt(index - 2);
+        } else if (isSpacer(after) && supportsLaunchers(appletAt(index + 1))) {
+            taskManager = appletAt(index + 1);
+            atStart = true;
+        }
+
+        if (!taskManager || urls.length === 0 || !urls.every(url => taskManager.backend.isApplication(url))) {
+            return false;
+        }
+        urls.forEach((url, i) => taskManager.addLauncher(url, atStart ? i : -1));
+        return true;
+    }
+
 //END functions

 //BEGIN connections
@@ -226,8 +256,11 @@ ContainmentItem {
         }

         onDrop: event => {
-            appletsModel.remove((dndSpacer.parent as AppletContainer).index);
-            root.processMimeData(event.mimeData, event.x, event.y);
+            const index = (dndSpacer.parent as AppletContainer).index;
+            appletsModel.remove(index);
+            if (!event.mimeData.hasUrls || !root.addLaunchersNextToSpacer(event.mimeData.urls, index)) {
+                root.processMimeData(event.mimeData, event.x, event.y);
+            }
             event.accept(event.proposedAction);
             root.fixedWidth = root.fixedHeight = 0;
         }
-- 
